from pathlib import Path
import re,shutil,datetime,hashlib
p=Path('/opt/kiwoom/dashboard-source/dist/index.html');s=p.read_text()
m=re.search(r'(<script id="auto-trading-execution-module">\n)(.*?)(\n</script>)',s,re.S);assert m
u=m[2];assert 'auto-running-strategy' not in u
u=u.replace("const card=","const strategyDefinitions={\n trend:['추세추종','종가 > 5일선 > 20일선 > 60일선, 20일선 상승. 20일 수익률 순.'],\n breakout:['돌파매매','직전 20일 고가 돌파, 거래량이 직전 20일 평균의 1.5배 이상. 거래량 배수 순.'],\n pullback:['눌림목매매','20일선 > 60일선, 20일선 상승. 20일선 ±3%, 직전 20일 고점 대비 -3~-12%. 20일선에 가까운 순.'],\n reversion:['평균회귀','20일 볼린저밴드 하단(평균−2표준편차) 이하, 단순 RSI(14) 35 이하. RSI 낮은 순.'],\n momentum:['모멘텀매매','20일 수익률 10% 이상, 5일 수익률 양수, 종가 > 20일선. 20일 수익률 순.']\n};\nconst card=",1)
u=re.sub(r"card.innerHTML=.*?;\n",lambda _: 'card.innerHTML=\'<h2>실제 자동매매</h2><p>선택한 시장·전략으로 실전 계좌에 지정가 주문을 전송합니다.</p><p id="auto-running-strategy" role="status" aria-live="polite">실행 전략을 확인하고 있습니다…</p><p id="auto-running-rule" class="muted"></p><p class="muted">종목당 1주 · 최대 5종목 · 익절 +5% / 손절 -3% · 정규장 60초 주기<br>자동매매로 체결된 보유분만 매도합니다. 지정가는 미체결될 수 있으며 손절 가격은 보장되지 않습니다.</p><label>자동매매 보유·미체결 매수 예산 <input id="auto-budget" type="number" min="1" step="1" value="500000" inputmode="numeric"> <span id="auto-currency">원</span></label><p class="muted">보유 매입금액과 미체결 매수를 기준으로 한도 적용 · 비용 여유 1% · 매도 후 예산 재사용</p><div class="auto-actions"><button type="button" id="auto-start">선택한 전략으로 실제 자동매매 시작</button><button type="button" id="auto-stop">이 시장 자동매매 중지</button></div><div id="auto-confirm" hidden><p id="auto-confirm-copy"></p><button type="button" id="auto-confirm-start">확인 후 실전 주문 자동 전송 시작</button> <button type="button" id="auto-cancel">취소</button></div><p id="auto-status" role="status" aria-live="polite">상태를 확인하고 있습니다…</p><div id="auto-orders"></div>\';\n',u,count=1)
u=re.sub(r"function render\(\)\{.*?status.textContent=",lambda _: "function render(){buttons();if(!data)return;const active=strategyDefinitions[data.strategy]?.[0]||names[data.strategy]||data.strategy;card.querySelector('#auto-running-strategy').textContent=(data.enabled?(data.global_enabled?'현재 실행 전략: ':'실행 대기 전략: '):'자동매매 중지 · 설정 전략: ')+(data.market==='KR'?'국내주식':'미국주식')+' · '+active;card.querySelector('#auto-running-rule').textContent='매수 후보 조건: '+(strategyDefinitions[data.strategy]?.[1]||'전략 조건을 확인할 수 없습니다.')+' 완료된 일봉으로 후보를 선정하고, 정규장에 연속 조회 거래량 증가가 확인되면 예산·보유·미체결 조건에 따라 지정가 매수를 시도합니다.';status.textContent=",u,count=1)
u=u.replace("data=null;status.textContent=e.message;","data=null;card.querySelector('#auto-running-strategy').textContent='실행 전략을 확인하지 못했습니다.';card.querySelector('#auto-running-rule').textContent='';status.textContent=e.message;")
u=u.replace("status.textContent='상태를 확인하고 있습니다…';orders.replaceChildren();","status.textContent='상태를 확인하고 있습니다…';card.querySelector('#auto-running-strategy').textContent='실행 전략을 확인하고 있습니다…';card.querySelector('#auto-running-rule').textContent='';orders.replaceChildren();")
assert u.count('id="auto-running-strategy"')==1
updated=s[:m.start(2)]+u+s[m.end(2):]
backup=str(p)+'.before-auto-strategy-description-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S');shutil.copy2(p,backup);p.write_text(updated)
print('UPDATED',backup,hashlib.sha256(u.encode()).hexdigest())
